const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toLocaleDateString('en-CA');
const dateLabel=s=>s?new Date(String(s).length===10?s+'T12:00:00':s).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'—';
const titleCase=s=>String(s||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',truck:'M2 6h12v11H2z M14 10h4l4 4v3h-8 M6 17a2 2 0 1 0 0 .01 M18 17a2 2 0 1 0 0 .01',book:'M4 3h14a2 2 0 0 1 2 2v16H6a2 2 0 0 1-2-2z M4 17h16 M8 7h8 M8 11h5',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 12h8 M8 16h6',fleet:'M2 8h11v9H2z M13 11h4l3 3v3h-7 M6 17a2 2 0 1 0 0 .01 M17 17a2 2 0 1 0 0 .01 M7 4h13v5',tool:'M14 6a5 5 0 0 0-6 6L3 17a2.8 2.8 0 0 0 4 4l5-5a5 5 0 0 0 6-6l-3 3-4-4z',chart:'M4 3v18h17 M8 16v-4 M13 16V8 M18 16V5',team:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M17 4a4 4 0 0 1 0 7 M22 21v-2a4 4 0 0 0-3-4',card:'M3 4h18v16H3z M3 9h18 M7 15h4',settings:'M9 3h6l1 3 3 1 2 5-2 2v4l-5 3-3-1-3 1-5-3v-4l-2-2 2-5 3-1z M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',arrow:'M5 12h14 M13 6l6 6-6 6',plus:'M12 5v14 M5 12h14',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',menu:'M3 6h18 M3 12h18 M3 18h18',clock:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M12 6v6l4 2',check:'M4 12l5 5L20 6',info:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M12 11v6 M12 7h.01',wallet:'M3 5h17v15H3z M3 5V3h14 M15 11h6v5h-6z',camera:'M3 7h4l2-3h6l2 3h4v14H3z M12 10a4 4 0 1 0 0 8 4 4 0 0 0 0-8'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
$$('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const pages={dashboard:'Overview',loads:'Loads',books:'Bookkeeping',documents:'Documents',fleet:'Fleet',operations:'Work center',reports:'Reports',insights:'Business Insights',payments:'Payments',team:'Team & access',billing:'Subscription',settings:'Company settings',platform:'Platform owner',invoices:'Invoices & bills',taxes:'Tax center',structure:'Business structure',trips:'Trip planner',appointments:'Appointments'};
let state={user:null,companies:[],company:null,role:null,items:[],files:[],members:[],invites:[],audit:[],usage:{},total:0,billingReady:false,platformAdmin:false};
let photoProcessor=null;
let taxYear=String(new Date().getFullYear());
let page='dashboard',month=today().slice(0,7),filter='all',search='',sequence=0,authSequence=0,busy=false,toastTimer,inviteToken=new URLSearchParams(location.hash.slice(1)).get('invite');
const client=window.supabase?.createClient(window.LEOS_CONFIG.url,window.LEOS_CONFIG.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
const endpoint=window.LEOS_CONFIG.url+'/functions/v1/leos-platform';
const manager=()=>['owner','admin'].includes(state.role);
function canWrite(kind){if(manager())return true;if(state.role==='dispatcher')return ['load','truck','maintenance','inspection','reminder'].includes(kind);if(state.role==='bookkeeper')return financeKinds.includes(kind)||kind==='taxDeadline';return ['driver','staff'].includes(state.role)&&['fuel','expense','inspection','reminder'].includes(kind);}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),6500);}
async function api(action,body={},companyId=state.company?.id){
 const session=await client.auth.getSession();if(session.error)throw session.error;
 const token=session.data.session?.access_token;
 const headers={apikey:window.LEOS_CONFIG.key,...(token?{Authorization:'Bearer '+token}:{})};
 let data;
 if(body instanceof FormData){body.set('action',action);if(companyId)body.set('companyId',companyId);data=body;}
 else{headers['Content-Type']='application/json';data=JSON.stringify({action,...body,...(companyId?{companyId}:{})});}
 const response=await fetch(endpoint,{method:'POST',headers,body:data});
 let result;try{result=await response.json();}catch{throw Error('The server could not be reached. Try again.');}
 if(!response.ok)throw Error(result.error||'This request could not be completed.');return result;
}
function wipe(){sequence++;state={...state,user:null,companies:[],company:null,role:null,items:[],files:[],members:[],invites:[],audit:[],usage:{},total:0,platformAdmin:false};search='';filter='all';$('#modal').close();$('#modal-content').innerHTML='';}
const businessTypes=[['general','General business'],['services','Services / consulting'],['retail','Retail / products'],['projects','Projects / contracting'],['trucking','Trucking / transportation']];
const taxTypes=[['income_estimate','Estimated income tax'],['income_return','Income tax return payment'],['sales','Sales / use tax'],['payroll','Payroll tax'],['property','Property tax'],['other','Other tax']];
const generalMode=()=>!!state.company&&(state.company.settings.businessType||'trucking')!=='trucking';
const financeAccess=()=>['owner','admin','bookkeeper'].includes(state.role);
function chrome(){
 $('#company-switch').innerHTML=state.companies.length?state.companies.map(c=>`<option value="${esc(c.id)}" ${c.id===state.company?.id?'selected':''}>${esc(c.name)}</option>`).join(''):'<option value="">'+(state.user?'Create your company':'Sign in to get started')+'</option>';
 for(const key of ['loads','fleet','trips'])$('#nav [data-page="'+key+'"]').hidden=generalMode();
 $('#nav [data-page="appointments"]').hidden=!!state.user&&!manager();
 $('#nav [data-page="taxes"]').hidden=!!state.user&&!financeAccess();
 $('#nav [data-page="payments"]').hidden=!!state.user&&!financeAccess();
 $('#nav [data-page="insights"]').hidden=!!state.user&&!financeAccess();
 const user=state.user;$('#account').innerHTML=user?`${esc(user.email?.split('@')[0]?.slice(0,16))}<span class="avatar">${esc(user.email?.slice(0,2).toUpperCase())}</span>`:'Sign in <span class="avatar">↗</span>';
 $('#platform-nav').hidden=!state.platformAdmin;$('#crumb-page').textContent=pages[page];
 $$('#nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false');});
}
async function bootstrap(preferred){
 const seq=++sequence;$('#main').innerHTML='<div class="loading"><span class="spinner"></span>Loading your companies…</div>';
 const data=await api('bootstrap');if(seq!==sequence)return;
 state={...state,companies:data.companies,platformAdmin:data.platformAdmin,billingReady:data.billingReady};
 const saved=localStorage.getItem('leos-company-'+state.user.id);const selected=data.companies.find(c=>c.id===(preferred||saved))||data.companies[0];
 if(selected)await loadCompany(selected.id);else{state.company=null;state.items=[];render();}
}
async function loadCompany(id){
 const seq=++sequence;state.company=null;state.items=[];state.files=[];state.members=[];state.invites=[];state.audit=[];state.total=0;state.role=null;search='';filter='all';$('#modal').close();
 $('#main').innerHTML='<div class="loading"><span class="spinner"></span>Opening your company…</div>';chrome();
 try{
  const data=await api('company_state',{},id);if(seq!==sequence)return;
  state={...state,...data};localStorage.setItem('leos-company-'+state.user.id,id);render();
 }catch(e){if(seq!==sequence)return;$('#main').innerHTML=`<div class="card"><div class="empty"><h3>Workspace unavailable</h3><p>${esc(e.message)}</p><button class="btn primary" data-action="reload">Try again</button></div></div>`;chrome();}
}
async function refresh(){if(!state.company)return bootstrap();const id=state.company.id,seq=++sequence;const data=await api('company_state',{},id);if(seq!==sequence)return;state={...state,...data};render();}
async function more(){const id=state.company?.id,seq=sequence;const result=await api('company_state',{offset:state.items.length},id);if(seq!==sequence)return;state.items=[...state.items,...result.items];state.files=[...new Map([...state.files,...result.files].map(f=>[f.id,f])).values()];state.total=result.total;render();}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function button(label,action,style='primary',ico='plus',attrs=''){return `<button class="btn ${style}" data-action="${action}" ${attrs}>${icon(ico)}${label}</button>`;}
function empty(ico,title,text,action=''){return `<div class="empty"><span class="empty-icon">${icon(ico)}</span><h3>${title}</h3><p>${text}</p>${action}</div>`;}
function period(){const months=[...new Set([today().slice(0,7),...state.items.map(i=>String(i.payload.date||i.created_at).slice(0,7))])].sort().reverse();return `<select class="period-select" id="period" aria-label="Reporting month"><option value="" ${month===''?'selected':''}>All dates</option>${months.map(m=>`<option value="${esc(m)}" ${m===month?'selected':''}>${new Date(m+'-15').toLocaleDateString('en-US',{month:'long',year:'numeric'})}</option>`).join('')}</select>`;}
function statusTag(s){const green=['paid','completed','done','active','trialing'].includes(s);const red=['past_due','unpaid','canceled','out_of_service'].includes(s);return `<span class="tag ${green?'green':red?'red':'orange'}">${esc(titleCase(s||'open'))}</span>`;}
function stat(label,value,note,ico){return `<div class="stat-card"><div class="stat-top">${label}${icon(ico)}</div><strong>${value}</strong><small>${note}</small></div>`;}
function rowsTable(items,kind='records'){
 if(!items.length)return empty(kind==='loads'?'truck':'book',kind==='loads'?'Your next load starts here':'A clean slate for your business',kind==='loads'?'Add a rate confirmation, track delivery, and follow the money through to payment.':'Add your company’s first record. Only members with access to this workspace can see it.',canWrite(kind==='loads'?'load':'expense')?button(kind==='loads'?'Add a load':'Add a record',kind==='loads'?'add-load':'add-record'):'');
 return `<div class="table-wrap"><table><thead><tr><th>${kind==='loads'?'Load / route':'Record'}</th><th>Date</th><th>Status</th><th>${kind==='loads'?'Gross rate':'Amount'}</th><th></th></tr></thead><tbody>${items.map(i=>{const p=i.payload;return `<tr><td><strong>${esc(kind==='loads'?(p.loadNo||p.description):p.description)}</strong><small>${esc(kind==='loads'?([p.origin,p.destination].filter(Boolean).join(' → ')||'Route not entered'):labels[i.kind]||i.kind)}</small></td><td>${esc(dateLabel(p.date||i.created_at))}</td><td>${statusTag(p.status)}</td><td><strong>${money(p.amount)}</strong>${kind==='loads'?`<small>${num(p.miles).toLocaleString()} mi</small>`:''}</td><td><button class="btn secondary small" data-action="detail" data-id="${esc(i.id)}">View ↗</button></td></tr>`;}).join('')}</tbody></table></div>`;
}
function limited(){return state.total>state.items.length?`<div class="notice info">Showing ${state.items.length.toLocaleString()} of ${state.total.toLocaleString()} records. Reports currently use loaded records. <button class="btn secondary small" data-action="more">Load next 1,000</button></div>`:'';}
function loadShareLabel(){const values=[...new Set(state.items.filter(i=>i.kind==='load'&&(!month||String(i.payload.date||'').startsWith(month))).map(i=>i.payload.payMode==='cpm'?'PER-MILE PAY':i.payload.payMode==='gross'?'100% LOAD SHARE':num(i.payload.loadShare??state.company.settings.loadShare??100)+'% LOAD SHARE'))];return values.length===1?values[0]:values.length?'PAY VARIES BY LOAD':num(state.company.settings.loadShare??100)+'% DEFAULT LOAD SHARE';}
function dashboard(){
 const s=summarize(state.items,state.company.settings,month);const upcoming=state.items.filter(i=>opKinds.includes(i.kind)&&i.payload.status!=='done').sort((a,b)=>String(a.payload.dueDate||'9999').localeCompare(String(b.payload.dueDate||'9999'))).slice(0,4);
 return heading('YOUR BUSINESS, IN VIEW','The road ahead.','Here’s where '+esc(state.company.name)+' stands'+(['driver','staff'].includes(state.role)?' · Your assigned activity.':'.'),period()+button('Add record','add-record','primary'))+
 `<div class="overview-grid"><div class="hero-card"><span class="eyebrow">OPERATING PROFIT · ${month?'THIS MONTH':'ALL DATES'}</span><div class="hero-number">${money(s.profit)}</div><p>Earned load pay less recorded operating expenses</p><div class="hero-foot"><span>${s.loads} load${s.loads===1?'':'s'} recorded <span style="color:#ffffff30;margin:0 9px">|</span> ${s.miles.toLocaleString()} earned miles</span><span class="tag">${loadShareLabel()}</span></div></div>
 <div class="quick-card"><div class="card-title"><h2>Keep business moving</h2><span class="eyebrow">QUICK ADD</span></div><div class="quick-list"><button data-action="add-load">${icon('truck')}New load</button><button data-action="add-expense">${icon('wallet')}Expense</button><button data-action="scan-delivery">${icon('camera')}Scan delivery</button><button data-action="add-maintenance">${icon('tool')}Maintenance</button></div></div></div>
 ${s.scheduled>0?`<div class="notice info">${money(s.scheduled)} in scheduled / in-transit load pay is not yet counted as earned. Upload delivery proof below to complete a matching load.</div>`:''}${canWrite('load')?photoPanel():''}<div class="stat-grid">${stat('Recorded revenue',money(s.revenue),'Completed and paid loads','chart')}${stat('Operating expenses',money(s.expenses),'Fuel, expenses and fees you paid','wallet')}${stat('Completed, unpaid',money(s.unpaid),'Follow up on outstanding loads','clock')}${stat('Tax reserve target',money(s.taxReserve),'Savings estimate · no taxes withheld','card')}</div>
 <div class="two-col"><section class="card"><div class="card-title"><div><h2>Recent activity</h2><p>The latest across your company</p></div><button class="text-link" data-page="books">View all →</button></div>${rowsTable(state.items.filter(i=>financeKinds.includes(i.kind)).slice(0,5))}</section>
 <section class="card"><div class="card-title"><div><h2>On your radar</h2><p>Maintenance, inspections & reminders</p></div>${icon('clock')}</div>${upcoming.length?upcoming.map(i=>`<div class="reminder-row"><span class="reminder-dot">${icon(i.kind==='maintenance'?'tool':'clock')}</span><div><strong>${esc(i.payload.description)}</strong><p>${esc(i.payload.vehicle||labels[i.kind])} · ${i.payload.dueDate?dateLabel(i.payload.dueDate):'No due date'}</p><button class="text-link" data-action="detail" data-id="${i.id}">Open record →</button></div></div>`).join(''):empty('check','Nothing overdue. Room to plan.','Add your next service, inspection, or document renewal here.')}<button class="btn secondary" style="width:100%;margin-top:12px" data-page="operations">Open work center ${icon('arrow')}</button></section></div>
 <div class="section-note">${icon('info')}Scheduled loads are projections. Settlements and owner draws do not count twice toward profit. Tax reserves are budgeting targets.</div>`;
}
function filtered(kinds){return state.items.filter(i=>kinds.includes(i.kind)&&(filter==='all'||i.kind===filter||i.payload.status===filter)&&(!search||JSON.stringify(i.payload).toLowerCase().includes(search.toLowerCase())));}
function filters(options,placeholder){return `<div class="filters"><div class="filter-buttons">${options.map(([v,l])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${l}</button>`).join('')}</div><input type="search" class="search" id="search-records" placeholder="${placeholder}" aria-label="${placeholder}" value="${esc(search)}"></div>`;}
function loadsPage(){return heading('DISPATCH TO DEPOSIT','Every mile. Every load.','Track rate confirmations, delivery and payment in one place.',canWrite('load')?button('New load','add-load'):'')+filters([['all','All loads'],['scheduled','Scheduled'],['in_transit','In transit'],['completed','Completed'],['paid','Paid']],'Search load, city or reference')+(canWrite('load')?photoPanel():'')+`<section class="card">${rowsTable(filtered(['load']),'loads')}</section>`;}
function booksPage(){return heading('KNOW YOUR NUMBERS','The books, together.',generalMode()?'Income, spending and owner activity in one place.':'Track spending, settlements and owner draws without counting income twice.',button('Export CSV','csv','secondary','download')+button('Add record','add-record'))+filters(generalMode()?[['all','All records'],['income','Income'],['expense','Expenses'],['contribution','Contributions'],['draw','Owner draws']]:[['all','All records'],['fuel','Fuel'],['expense','Expenses'],['settlement','Settlements'],['draw','Owner draws']],'Search descriptions or notes')+`<section class="card">${rowsTable(filtered(financeKinds))}</section>`;}
function fleetPage(){const trucks=state.items.filter(i=>i.kind==='truck');return heading('YOUR EQUIPMENT','A home for your fleet.','Track trucks and their service history.',canWrite('truck')?button('Add truck','add-truck'):'')+`<div class="stat-grid">${stat('Active trucks',trucks.filter(i=>i.payload.status!=='out_of_service').length,'Available in this workspace','truck')}${stat('Out of service',trucks.filter(i=>i.payload.status==='out_of_service').length,'Recorded equipment status','tool')}${stat('Maintenance items',state.items.filter(i=>i.kind==='maintenance'&&i.payload.status!=='done').length,'Open service tasks','clock')}${stat('Plan capacity',state.usage.trucks+' / '+planLimits().trucks,'Trucks in your subscription','fleet')}</div><section class="card">${trucks.length?`<div class="table-wrap"><table><thead><tr><th>Truck</th><th>Vehicle</th><th>Status</th><th>Odometer</th><th></th></tr></thead><tbody>${trucks.map(i=>`<tr><td><strong>${esc(i.payload.description)}</strong><small>Unit ${esc(i.payload.unit||'—')}</small></td><td>${esc([i.payload.year,i.payload.make,i.payload.model].filter(Boolean).join(' ')||'—')}</td><td>${statusTag(i.payload.status)}</td><td>${num(i.payload.odometer).toLocaleString()} mi</td><td><button class="btn secondary small" data-action="detail" data-id="${i.id}">View ↗</button></td></tr>`).join('')}</tbody></table></div>`:empty('fleet','Bring your equipment into view.','Add your first truck to start keeping maintenance and inspection records together.',canWrite('truck')?button('Add truck','add-truck'):'')}</section>`;}
function opsPage(){return heading('STAY AHEAD OF THE ROAD','Your work center.','Service, inspections, and document renewals—before they become surprises.',button('Add task','add-task'))+filters([['all','All tasks'],['maintenance','Maintenance'],['inspection','Inspections'],['reminder','Reminders']],'Search vehicle or task')+`<section class="card">${filtered(opKinds).length?`<div class="table-wrap"><table><thead><tr><th>Task</th><th>Vehicle</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody>${filtered(opKinds).map(i=>`<tr><td><strong>${esc(i.payload.description)}</strong><small>${labels[i.kind]}</small></td><td>${esc(i.payload.vehicle||'—')}</td><td>${dateLabel(i.payload.dueDate)}</td><td>${statusTag(i.payload.status)}</td><td><button class="btn secondary small" data-action="detail" data-id="${i.id}">View ↗</button></td></tr>`).join('')}</tbody></table></div>`:empty('tool','Stay a step ahead.','Log an inspection, schedule maintenance, or set a document renewal reminder.',button('Add a task','add-task'))}</section><p class="section-note">${icon('info')}Reminders appear inside your dashboard. Email and push notifications are not enabled.</p>`;}
function documentsPage(){return heading('THE PAPER TRAIL','Every document, in place.','Private PDFs and photos, linked to your company records.',button('Upload document','upload','primary','file'))+(!generalMode()&&canWrite('load')?photoPanel():'')+`<div class="notice info">PDF, JPG, PNG and WebP · Up to 10 MB per file · Links expire after five minutes.</div>${state.files.length?`<div class="document-grid">${state.files.map(f=>`<article class="document-card">${icon(f.mime?.startsWith('image/')?'camera':'file')}<h3>${esc(f.name)}</h3><p>${dateLabel(f.created_at)}${f.size?' · '+(f.size/1024/1024).toFixed(2)+' MB':''}</p><p>${esc(state.items.find(i=>i.id===f.item_id)?.payload.description||'Company document')}</p><button class="btn secondary small" data-action="open-file" data-id="${f.id}">Open document ↗</button>${!generalMode()&&canWrite('load')&&f.mime?.startsWith('image/')?`<button class="btn primary small" style="margin-top:10px" data-action="scan-file" data-id="${f.id}">Analyze delivery photo</button>`:''}</article>`).join('')}</div>`:`<section class="card">${empty('file','Less paper. More peace of mind.','Upload rate confirmations, receipts, inspection forms, and renewal documents.',button('Upload your first document','upload','primary','file'))}</section>`}`;}
function reportsPage(){const s=summarize(state.items,state.company.settings,month);const row=(l,v,cls='')=>`<div class="${cls}"><span>${l}</span><strong>${money(v)}</strong></div>`;return heading('THE BUSINESS BEHIND THE MILES','Your numbers, clearly.','Based on recorded transactions in this workspace.',period()+button('Export CSV','csv','secondary','download')+button('Print report','print','secondary','file'))+`<div class="print-title">${esc(state.company.name)} · ${esc(month||'All dates')} · LEOS PhotoBooks 7.1</div><div class="two-col"><section class="card"><div class="card-title"><h2>Operating statement</h2><span class="tag">${esc(month||'All dates')}</span></div><div class="report-list">${row('Earned loads + other income',s.revenue)}${row('Recorded operating expenses',-s.expenses)}${row('Confirmed fuel reimbursements',s.credits)}${row('Operating profit',s.profit,'total')}${row('Tax reserve target (budget)',s.taxReserve)}${row('Owner draws (separate from expenses)',s.draws)}</div></section><section class="card"><h2>On the horizon</h2><div class="report-list">${row('Completed, unpaid loads',s.unpaid)}${row('Scheduled / in-transit load pay',s.scheduled)}<div><span>Earned miles</span><strong>${s.miles.toLocaleString()} mi</strong></div>${row('Recorded expense per earned mile',s.costPerMile)}</div></section></div><div class="section-note">${icon('info')}This is a bookkeeping summary, not a tax filing or cash-flow statement. Settlements are tracked separately to avoid counting load income twice. Expenses paid by another company with no business deduction are excluded from your operating costs. ${['driver','staff'].includes(state.role)?'Only your accessible records are included.':''}</div>`;}
function teamPage(){
 if(!manager())return heading('COMPANY ACCESS','Your team.','Your role: '+esc(titleCase(state.role)))+`<section class="card">${empty('team','Your workspace is connected.','The company owner or an administrator manages team invitations and access.')}</section>`;
 return heading('BETTER, TOGETHER','The people behind the miles.','Invite your team. Give each person the access their job needs.',button('Invite member','invite','primary','team'))+`<div class="notice info">Drivers see records they create or are assigned. Dispatchers manage loads and operations. Bookkeepers manage financial records. Only owners manage billing and team roles.</div><section class="card"><div class="card-title"><h2>Team members</h2><span class="tag">${state.members.length} / ${planLimits().members} seats</span></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Role</th><th>Joined</th><th></th></tr></thead><tbody>${state.members.map(m=>`<tr><td><strong>${esc(m.email)}</strong>${m.user_id===state.user.id?'<small>You</small>':''}</td><td>${statusTag(m.role)}</td><td>${dateLabel(m.joined_at)}</td><td>${state.role==='owner'&&m.role!=='owner'?`<button class="btn secondary small" data-action="edit-member" data-id="${m.user_id}">Manage</button>`:''}</td></tr>`).join('')}</tbody></table></div></section><section class="card" style="margin-top:20px"><div class="card-title"><h2>Pending invitations</h2><span class="tag">Expires in 7 days</span></div>${state.invites.length?`<div class="table-wrap"><table><thead><tr><th>Email</th><th>Role</th><th>Expires</th><th></th></tr></thead><tbody>${state.invites.map(i=>`<tr><td>${esc(i.email)}</td><td>${statusTag(i.role)}</td><td>${dateLabel(i.expires_at)}</td><td>${i.role!=='admin'||state.role==='owner'?`<button class="btn secondary small" data-action="revoke-invite" data-id="${i.id}">Revoke</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<p class="section-note">No pending invitations. Create an invite link when your next team member is ready.</p>'}</section>`;
}
function planLimits(){return {preview:{trucks:25,members:10},solo:{trucks:1,members:1},small_fleet:{trucks:5,members:10},fleet:{trucks:25,members:50}}[state.company?.plan]||{trucks:25,members:10};}
function billingPage(){
 const company=state.company,lim=planLimits();
 return heading('ROOM TO GROW','One workspace. Your whole business.','Your subscription belongs to this company—not individual drivers.',state.role==='owner'&&state.billingReady?button('Manage billing','portal','secondary','card'):'')+
 (!state.billingReady?'<div class="notice"><strong>Early access · Payments are not active.</strong> You can use your company workspace while subscription setup is completed. No payment card is being charged. Final prices have not been published.</div>':'<div class="notice info">Review the final price and billing interval in secure Stripe Checkout. Access updates after the payment provider confirms your subscription.</div>')+
 `<div class="two-col"><section class="card"><div class="card-title"><h2>Current workspace</h2>${statusTag(company.subscription_status)}</div><h3>${esc(company.plan==='preview'?'Early access':generalMode()?({solo:'Solo',small_fleet:'Business',fleet:'Team'}[company.plan]||titleCase(company.plan)):titleCase(company.plan))}</h3><p class="section-note">${company.current_period_end?'Current billing period ends '+dateLabel(company.current_period_end)+'.':'Your records stay available for viewing and export even if billing requires attention.'}${company.cancel_at_period_end?' Cancellation is scheduled at the end of this period.':''}</p></section><section class="card"><h2>Workspace usage</h2>${[...(!generalMode()?[['Trucks',state.usage.trucks||0,lim.trucks]]:[]),['Team members',state.usage.members||0,lim.members]].map(([l,n,max])=>`<div class="usage-row"><div><span>${l}</span><strong>${n} / ${max}</strong></div><div class="progress-bar"><span style="width:${Math.min(100,n/max*100)}%"></span></div></div>`).join('')}</section></div>
 <div class="plans">${[['solo','Solo','For the independent business.',1,1],['small_fleet',generalMode()?'Business':'Small Fleet',generalMode()?'Bring the team and the books together.':'Bring dispatch and the books together.',5,10],['fleet',generalMode()?'Team':'Fleet','More people. One clear picture.',25,50]].map(([key,name,desc,trucks,members])=>`<article class="plan ${key==='small_fleet'?'featured':''}"><span class="eyebrow">${key==='small_fleet'?'BUILT FOR TEAMS':'GROW AT YOUR PACE'}</span><h2 style="margin-top:14px;font-size:22px">${name}</h2><p>${desc}</p><div class="plan-price">${state.billingReady?'Choose billing':'Pricing coming soon'}</div><p>${state.billingReady?'Final price shown before payment.':'No checkout or automatic charge.'}</p><ul>${generalMode()?'':`<li>${trucks} truck${trucks>1?'s':''}</li>`}<li>${members} team member${members>1?'s':''}</li><li>Loads, records & documents</li><li>Reports & company exports</li></ul>${state.role==='owner'&&state.billingReady?`<button class="btn ${key==='small_fleet'?'primary':'secondary'}" data-action="choose-plan" data-plan="${key}">Choose ${name} ${icon('arrow')}</button>`:'<span class="tag">'+(state.role==='owner'?'Early access available':'Owner manages subscription')+'</span>'}</article>`).join('')}</div>`;
}
function settingsPage(){return heading('MAKE IT YOURS','Your company, your way.','Company settings apply to shared workspace reports.')+`<div class="two-col"><section class="card"><div class="card-title"><h2>Company preferences</h2>${statusTag(state.role)}</div><form id="company-settings"><div class="form-grid"><label class="field full">Company name<input name="name" value="${esc(state.company.name)}" required minlength="2" maxlength="90" ${!manager()?'disabled':''}></label>${settingsExtraFields()}<label class="field">Default load share (%)<input name="loadShare" type="number" min="0" max="100" step="0.01" value="${num(state.company.settings.loadShare??100)}" ${!manager()?'disabled':''}><small>Used when a load has no individual percentage.</small></label><label class="field">Tax reserve target (%)<input name="taxReserve" type="number" min="0" max="60" step="0.01" value="${num(state.company.settings.taxReserve??25)}" ${!manager()?'disabled':''}><small>A savings budget, not tax withholding.</small></label></div><div class="form-error"></div>${manager()?'<div class="form-actions"><button class="btn primary">Save preferences</button></div>':'<p class="section-note">Only an owner or administrator can change company preferences.</p>'}</form></section><section class="card"><h2>Personal records, preserved.</h2><p class="section-note">Your original PhotoBooks records and receipt files remain in your personal account. Copying them here creates separate company records that your authorized team can see. Future edits are not synchronized between the copies.</p>${state.role==='owner'?button('Copy my personal records','import','secondary','book'):''}<a class="btn secondary" style="margin-top:12px" href="/personal.html">Open personal toolkit ${icon('arrow')}</a></section></div><section class="card" style="margin-top:20px"><div class="card-title"><h2>Backups & company history</h2>${!['driver','staff'].includes(state.role)?button('Export company JSON','export','secondary','download'):''}</div><p class="section-note">Exports contain bookkeeping data and document references. Original files can be downloaded from Documents. Archived records stay in company exports.</p>${manager()?`<div class="table-wrap"><table><thead><tr><th>Action</th><th>When</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td>${esc(titleCase(a.action.replaceAll('.',' ')))}</td><td>${esc(new Date(a.created_at).toLocaleString())}</td></tr>`).join('')||'<tr><td colspan="2" class="table-empty">No company history yet.</td></tr>'}</tbody></table></div>`:''}</section>`;}
function landing(){return `<div class="landing"><div class="landing-hero"><div><span class="eyebrow">MEET PHOTOBOOKS 8.0</span><h1>Your business.<br><em>All together.</em></h1><p class="intro">From your first invoice to your next big milestone. Give your company one workspace for the road, the books, and the people moving it forward.</p><div class="actions">${button('Start your company','create-company','primary','arrow')}${button('Sign in','login','secondary','team')}</div><div class="trust">${icon('check')}Private company workspaces · Role-based team access</div></div><div class="landing-art"><div class="road"></div><div class="art-head"><span>THE BUSINESS WORKSPACE</span><span class="tag">8.0 EARLY ACCESS</span></div><h2>More clarity.<br>A business in motion.</h2><div class="art-modules"><span>${icon('truck')}Invoices & payments</span><span>${icon('book')}Books & expenses</span><span>${icon('fleet')}Tax records & deadlines</span><span>${icon('team')}People & access</span></div></div></div><div class="feature-strip"><article class="card">${icon('truck')}<h3>From invoice to paid.</h3><p>Keep customer invoices, incoming payments, expenses and business documents together.</p></article><article class="card">${icon('book')}<h3>A clearer picture of profit.</h3><p>Track income, expenses, tax payments and owner draws. Export records when it’s time to close the books.</p></article><article class="card">${icon('team')}<h3>Your company. Your people.</h3><p>Invite staff, managers, drivers and bookkeepers. Keep each company’s information private and separate.</p></article></div><div class="landing-bottom"><span>Existing customer? Your personal records and receipts are still here.</span><a href="/personal.html" class="text-link">Open your personal toolkit →</a></div><div class="notice info">Early access is open. Subscription payments and final pricing are not active yet.</div></div>`;}
function onboarding(){return heading('YOUR NEXT CHAPTER','Let’s make it your own.','Create a private company workspace, or accept an invitation from your team.')+`<section class="card">${empty('fleet','One company. Everything connected.','Start with your company name. Choose your business type, invite your team, and bring the books together as you go.',button('Create your company','create-company'))}</section><div class="notice info" style="margin-top:20px">Your personal records are unchanged. After creating a workspace, you can choose to copy them from Company settings.</div>`;}
function render(){photoProcessor=null;chrome();if(!state.user){$('#main').innerHTML=landing();return;}if(!state.company){$('#main').innerHTML=onboarding();return;}let content={payments:()=>paymentsPage({items:state.items,settings:state.company.settings,month,allowed:financeAccess(),esc,period:period()}),insights:()=>insightsPage({items:state.items,files:state.files,settings:state.company.settings,total:state.total,allowed:financeAccess(),esc,asOf:today()}),dashboard:generalMode()?generalDashboard:dashboard,trips:tripPage,appointments:schedulingPage,loads:loadsPage,books:booksPage,fleet:fleetPage,operations:opsPage,documents:documentsPage,reports:generalMode()?generalReports:reportsPage,taxes:taxesPage,invoices:invoicesPage,structure:structurePage,team:teamPage,billing:billingPage,settings:settingsPage}[page];$('#main').innerHTML=(state.company.suspended?'<div class="notice">This company is suspended. Your records remain stored. Contact the platform owner.</div>':'')+(!['active','trialing','preview'].includes(state.company.subscription_status)?'<div class="notice">This workspace is read-only while billing needs attention. Viewing and export remain available.</div>':'')+limited()+(['documents','dashboard'].includes(page)&&financeAccess()?smartUploadPanel():'')+(content?content():'<div class="loading"><span class="spinner"></span>Loading platform overview…</div>');if(page==='platform')loadPlatform();if(page==='trips')initTripPlanner();if(page==='appointments')initScheduling();if(['loads','documents','dashboard'].includes(page)&&!generalMode()&&canWrite('load'))initPhotoCompletion();if(['documents','dashboard'].includes(page)&&financeAccess())initSmartUpload();}
function generalDashboard(){
 const s=summarize(state.items,state.company.settings,month);
 const reminders=state.items.filter(i=>opKinds.includes(i.kind)&&i.payload.status!=='done').sort((a,b)=>String(a.payload.dueDate||'9999').localeCompare(String(b.payload.dueDate||'9999'))).slice(0,5);
 const goals=state.company.settings;
 return heading('YOUR BUSINESS, IN VIEW','The bigger picture.','Income, spending and the next things that need your attention.',period()+button('Record income','add-income'))+
 `<div class="overview-grid"><div class="hero-card"><span class="eyebrow">RECORDED OPERATING PROFIT · ${month?'SELECTED MONTH':'ALL DATES'}</span><div class="hero-number">${money(s.profit)}</div><p>Recorded income less operating expenses · not a bank balance</p><div class="hero-foot"><span>${esc(state.company.name)}</span><span class="tag">${esc((businessTypes.find(([key])=>key===goals.businessType)||['','General business'])[1])}</span></div></div><section class="quick-card"><div class="card-title"><h2>Keep business moving</h2><span class="eyebrow">QUICK ADD</span></div><div class="quick-list"><button data-action="add-income">${icon('wallet')}Income</button><button data-action="add-expense">${icon('book')}Expense</button><button data-action="add-invoice">${icon('file')}Invoice</button><button data-action="add-tax-payment">${icon('card')}Tax payment</button></div></section></div>
 <div class="stat-grid">${stat('Recorded revenue',money(s.revenue),'Income received + any earned legacy loads','chart')}${stat('Operating expenses',money(s.expenses),'Excludes owner draws and tax-payment records','wallet')}${stat('Customer invoices unpaid',money(s.invoicesDue),'All open invoices, across all dates','file')}${stat('Business bills unpaid',money(s.billsDue),'All open bills, across all dates','clock')}</div>
 <div class="two-col"><section class="card"><div class="card-title"><div><h2>Recent business activity</h2><p>Income, expenses and the paper trail</p></div><button data-page="books" class="text-link">View all →</button></div>${rowsTable(state.items.filter(i=>financeKinds.includes(i.kind)).slice(0,5))}</section><section class="card"><div class="card-title"><h2>What needs attention</h2>${icon('clock')}</div>${reminders.length?reminders.map(i=>`<div class="reminder-row"><span class="reminder-dot">${icon(i.kind==='taxDeadline'?'card':'clock')}</span><div><strong>${esc(i.payload.description)}</strong><p>${esc(labels[i.kind])} · ${dateLabel(i.payload.dueDate)}</p><button class="text-link" data-action="detail" data-id="${i.id}">Open →</button></div></div>`).join(''):empty('check','Your next move, in focus.','Add an important renewal, a task or a tax deadline to keep it on your radar.')}<button class="btn secondary" style="width:100%;margin-top:15px" data-page="taxes">Open tax center ${icon('arrow')}</button></section></div>
 <div class="two-col"><section class="card"><h2>Targets for the selected period</h2><div class="report-list"><div><span>Monthly revenue goal</span><strong>${num(goals.monthlyRevenueGoal)?money(goals.monthlyRevenueGoal):'Not set'}</strong></div><div><span>Monthly expense budget</span><strong>${num(goals.monthlyExpenseBudget)?money(goals.monthlyExpenseBudget):'Not set'}</strong></div></div><button data-page="settings" class="text-link" style="margin-top:14px">Set your business targets →</button></section><section class="card"><h2>Owner activity</h2><div class="report-list"><div><span>Owner contributions</span><strong>${money(s.contributions)}</strong></div><div><span>Owner draws</span><strong>${money(s.draws)}</strong></div></div><p class="section-note">Contributions and draws stay separate from operating revenue and expenses.</p></section></div>`;
}
function invoicesPage(){
 const items=filtered(['invoice','bill']),s=summarize(state.items,state.company.settings);
 return heading('FROM PROMISE TO PAYMENT','Invoices & bills.','Track what customers owe and what your business needs to pay.',financeAccess()?button('New invoice','add-invoice')+button('New bill','add-bill','secondary','file'):'')+
 `<div class="stat-grid">${stat('Customers owe',money(s.invoicesDue),'Unpaid customer invoices','file')}${stat('Business owes',money(s.billsDue),'Unpaid bills','clock')}${stat('Recorded invoices',state.items.filter(i=>i.kind==='invoice').length,'Company invoice records','book')}${stat('Recorded bills',state.items.filter(i=>i.kind==='bill').length,'Company bill records','wallet')}</div>`+
 filters([['all','All'],['invoice','Customer invoices'],['bill','Business bills']],'Search customer, vendor or reference')+
 `<section class="card">${rowsTable(items)}</section><div class="notice info" style="margin-top:20px">Open invoices and bills are not included again in profit. After a full payment has already happened, use <strong>Record payment</strong> to create one linked income or expense entry. This records bookkeeping only; it does not charge a customer or move money. Partial payments and automatic invoice delivery are not enabled.</div>`;
}
function generalReports(){
 const s=summarize(state.items,state.company.settings,month),year=(month||today()).slice(0,4);
 const r=(l,v,cls='')=>`<div class="${cls}"><span>${l}</span><strong>${money(v)}</strong></div>`;
 return heading('ANALYTICS FOR YOUR BUSINESS','See the movement.','Actual recorded activity, with invoices and bills kept separate from payments.',period()+button('Export CSV','csv','secondary','download'))+
 `<div class="two-col"><section class="card"><h2>Operating summary</h2><div class="report-list">${r('Recorded revenue',s.revenue)}${r('Operating expenses',-s.expenses)}${r('Confirmed fuel reimbursements',s.credits)}${r('Operating profit',s.profit,'total')}${r('Savings target for taxes (budget)',s.taxReserve)}</div></section><section class="card"><h2>Recorded cash movement</h2><div class="report-list">${r('Owner contributions',s.contributions)}${r('Owner draws',s.draws)}${r('Tax payments logged by payment date',s.taxPaid)}${r('Net movement in recorded transactions',s.cashMovement,'total')}</div><p class="section-note">This is not a reconciled bank balance. It includes recorded payments, contributions and draws. Any completed-but-unpaid legacy load revenue is excluded from cash movement.</p></section></div>
 <section class="card" style="margin-top:20px"><div class="card-title"><h2>${year} · Monthly performance</h2><span class="tag">Recorded activity</span></div><div class="table-wrap"><table><thead><tr><th>Month</th><th>Revenue</th><th>Expenses</th><th>Operating profit</th><th>Net recorded cash</th></tr></thead><tbody>${Array.from({length:12},(_,index)=>{const m=year+'-'+String(index+1).padStart(2,'0'),x=summarize(state.items,state.company.settings,m);return `<tr><td>${new Date(m+'-15').toLocaleDateString('en-US',{month:'long'})}</td><td>${money(x.revenue)}</td><td>${money(x.expenses)}</td><td><strong>${money(x.profit)}</strong></td><td>${money(x.cashMovement)}</td></tr>`;}).join('')}</tbody></table></div></section><p class="section-note">These are bookkeeping summaries, not a tax return, a balance sheet or a reconciled cash-flow statement. Tax payment treatment should be reviewed separately with your tax professional.</p>`;
}
function settingsExtraFields(){
 const s=state.company.settings,disabled=!manager()?'disabled':'';
 return `<label class="field full">Business type<select name="businessType" ${disabled}>${businessTypes.map(([key,label])=>`<option value="${key}" ${(s.businessType||'trucking')===key?'selected':''}>${label}</option>`).join('')}</select><small>General Business mode hides truck and load navigation. Existing records stay stored.</small></label><label class="field">Entity label (self-reported)<select name="entityType" ${disabled}>${[['','Not specified'],['sole_proprietor','Sole proprietor'],['llc','LLC'],['corporation','Corporation'],['partnership','Partnership'],['nonprofit','Nonprofit'],['other','Other']].map(([key,label])=>`<option value="${key}" ${s.entityType===key?'selected':''}>${label}</option>`).join('')}</select></label>${field('State / region','region',s.region||'','text',disabled)}${field('Fiscal-year end (informational)','fiscalYearEnd',s.fiscalYearEnd||'','text',disabled)}${field('Monthly revenue goal ($)','monthlyRevenueGoal',s.monthlyRevenueGoal||'','number','min="0" step="0.01" '+disabled)}${field('Monthly expense budget ($)','monthlyExpenseBudget',s.monthlyExpenseBudget||'','number','min="0" step="0.01" '+disabled)}<label class="field full">What the business does<textarea name="businessDescription" maxlength="1000" ${disabled}>${esc(s.businessDescription||'')}</textarea></label>`;
}
function structurePage(){
 const s=state.company.settings;
 return heading('THE FOUNDATION OF YOUR BUSINESS','A clearer company structure.','Keep the business profile, responsibilities and records together.',manager()?button('Edit business profile','structure-settings','secondary','settings'):'')+
 `<div class="two-col"><section class="card"><h2>Business profile</h2><div class="detail-grid">${[['Business name',state.company.name],['Business type',(businessTypes.find(([key])=>key===(s.businessType||'trucking'))||['','General business'])[1]],['Entity label',titleCase(s.entityType||'Not specified')],['State / region',s.region||'Not specified'],['Fiscal-year end',s.fiscalYearEnd||'Not specified'],['Workspace owner',state.members.find(m=>m.role==='owner')?.email||'Managed by company owner']].map(([l,v])=>`<div><small>${esc(l)}</small><p>${esc(v)}</p></div>`).join('')}</div><p class="section-note">${esc(s.businessDescription||'Add a business description in Company settings.')}</p></section><section class="card"><h2>Who handles what</h2><div class="reminder-row"><div><strong>Owner / administrator</strong><p>Company settings, records, team access and business oversight. Billing is owner-only.</p></div></div><div class="reminder-row"><div><strong>Bookkeeper</strong><p>Financial records, invoices, bills, tax tracking and exports.</p></div></div><div class="reminder-row"><div><strong>Staff / driver</strong><p>Own and assigned records, plus permitted expense and task submissions.</p></div></div><button class="btn secondary" data-page="team" style="margin-top:15px">Manage team access ${icon('team')}</button></section></div><div class="two-col"><section class="card"><h2>Company documents</h2><p class="section-note">Keep formation documents, insurance, licenses, contracts and meeting records in private company storage. Avoid entering sensitive identifiers into public profile fields.</p><button class="btn secondary" data-page="documents">Open documents ${icon('file')}</button></section><section class="card"><h2>Business review checklist</h2><div class="report-list"><div><span>Company profile</span><strong>${s.entityType&&s.region?'Details entered':'Add details'}</strong></div><div><span>Team access</span><strong>${state.usage.members||1} member(s)</strong></div><div><span>Financial goals</span><strong>${s.monthlyRevenueGoal||s.monthlyExpenseBudget?'Targets entered':'Not set'}</strong></div><div><span>Tax recordkeeping</span><button class="text-link" data-page="taxes">Open tax center →</button></div></div></section></div><p class="section-note">This profile organizes your information; it does not form a legal entity, verify tax elections or certify compliance.</p>`;
}
function taxesPage(){
 if(!financeAccess())return heading('TAX RECORDKEEPING','Company tax center.','Available to owners, administrators and bookkeepers.')+`<section class="card">${empty('card','Financial access required.','Ask your company owner about access to tax records.')}</section>`;
 const data=taxSummary(state.items,state.files,taxYear,state.company.settings);
 const years=[...new Set([String(new Date().getFullYear()),taxYear,...state.items.map(i=>String(i.payload.taxYear||i.payload.date||i.created_at).slice(0,4))])].filter(y=>/^\d{4}$/.test(y)).sort().reverse();
 const actions=`<select id="tax-year" class="period-select" aria-label="Tax year">${years.map(y=>`<option value="${y}" ${y===taxYear?'selected':''}>Tax year ${y}</option>`).join('')}</select>`+button('Record tax payment','add-tax-payment')+button('Tax export','tax-export','secondary','download');
 return heading('EVERYTHING IN ITS PLACE','Your tax center.','Tax payments, supporting records and deadlines—organized for review.',actions)+
 `<div class="notice info"><strong>Tracking and preparation.</strong> This section does not file or pay taxes, determine deductions, or calculate your tax liability. Savings targets are your own budgeting percentages. Set deadlines that apply to your business with your tax professional.</div>
 <div class="stat-grid">${stat('Tax payments recorded',money(data.paid),'Logged against tax year '+taxYear,'card')}${stat('Savings target for taxes',money(data.reserve),'Calendar-year operating-profit budget','wallet')}${stat('Expenses to review',data.needsReview.length,'Unclassified / needs accountant review','book')}${stat('Expenses without attachments',data.missingDocuments.length,'Documents to gather, not a deductibility test','file')}</div>
 <div class="two-col"><section class="card"><div class="card-title"><h2>Payment record by tax type</h2><span class="tag">${taxYear}</span></div><div class="report-list">${taxTypes.map(([key,label])=>`<div><span>${label}</span><strong>${money(data.byType[key])}</strong></div>`).join('')}</div><p class="section-note">Tax payments are kept separate from operating expenses in this app. Your tax professional should determine their return treatment.</p></section><section class="card"><div class="card-title"><h2>Tax deadlines</h2>${button('Add deadline','add-tax-deadline','secondary small','plus')}</div>${data.deadlines.length?data.deadlines.sort((a,b)=>String(a.payload.dueDate).localeCompare(String(b.payload.dueDate))).map(i=>`<div class="reminder-row"><span class="reminder-dot">${icon('clock')}</span><div><strong>${esc(i.payload.description)}</strong><p>${dateLabel(i.payload.dueDate)} · ${esc(i.payload.jurisdiction||'Agency not entered')}</p>${statusTag(i.payload.status)} <button class="text-link" data-action="detail" data-id="${i.id}">Open →</button></div></div>`).join(''):empty('clock','Your calendar, your obligations.','Add only the filing or payment deadlines that apply to this business. No universal quarterly schedule is assumed.')}<p class="section-note">Reminders appear in the app. Email and push delivery are not enabled.</p></section></div>
 <section class="card" style="margin-top:20px"><div class="card-title"><h2>Tax payment history</h2><span class="tag">${data.payments.length} records</span></div>${rowsTable(data.payments)}</section>
 <section class="card" style="margin-top:20px"><div class="card-title"><h2>Expense review queue</h2><span class="tag">${data.needsReview.length} to review</span></div>${rowsTable(data.needsReview)}<p class="section-note">“Reviewed” is a workflow label, not proof that an expense is deductible. Attach records and have the appropriate tax treatment confirmed.</p></section>
 <section class="card" style="margin-top:20px"><h2>Official U.S. recordkeeping references</h2><p class="section-note">Requirements vary by business and jurisdiction. These references explain the federal recordkeeping foundation.</p><div class="actions"><a class="btn secondary" href="https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep" target="_blank" rel="noopener noreferrer">IRS recordkeeping ↗</a><a class="btn secondary" href="https://www.irs.gov/businesses/small-businesses-self-employed/estimated-taxes" target="_blank" rel="noopener noreferrer">IRS estimated taxes ↗</a></div></section>`;
}
function paymentForm(id){
 const item=state.items.find(i=>i.id===id);if(!item||!financeAccess()||!['invoice','bill','load'].includes(item.kind))return toast('Financial access required.');
 if(item.payload.status==='paid')return toast('This payment is already recorded.');
 if(item.kind==='load'&&item.payload.status!=='completed')return toast('Complete delivery before confirming load payment.');
 const amount=remainingAmount(item,item.kind==='load'?loadPaymentAmount(item,state.company.settings):num(item.payload.amount));if(!(amount>0))return toast('Enter a positive amount before confirming payment.');
 modal(`<h2 id="modal-title">${item.kind==='bill'?'Confirm bill paid.':'Confirm payment received.'}</h2><p class="lead">${esc(item.payload.description)} · <strong>${money(amount)}</strong></p><div class="notice">Balance remaining: ${money(amount)}. Confirm only the amount that has actually ${item.kind==='bill'?'been paid':'been received'}. ${item.kind==='load'?'This clears the unpaid load balance without adding earned income twice.':'Leo reduces this balance and creates a linked '+(item.kind==='bill'?'expense':'income')+' entry.'} No money is moved.</div>${item.payload.appointmentId?'<p class="section-note">This invoice started with the listed appointment price. Check final charges and taxes first; use Review/Edit invoice if the amount needs changing.</p>':''}<form id="payment-form" data-id="${id}" data-version="${item.version}" data-company="${state.company.id}" data-user="${state.user.id}" data-payment-id="${crypto.randomUUID()}">${field('Amount received / paid','amount',amount,'number','required min="0.01" step="0.01" max="'+amount+'"')}${selectField('Payment type','paymentType',item.kind==='invoice'?[['payment','Payment / installment'],['deposit','Deposit against this invoice']]:[['payment','Payment / installment']],'payment')}${field('Actual payment date','date',today(),'date','required max="'+today()+'"')}${selectField('Payment method','method',paymentMethods,'bank_transfer')}${field('Payment / transaction reference (optional)','reference','','text','maxlength="120"')}<label class="field"><span><input type="checkbox" name="verified" required> I verified this payment amount was received or paid.</span></label><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="btn secondary" data-action="edit-record" data-id="${id}">Review / edit record</button><button class="btn primary" type="submit">Confirm payment ${icon('check')}</button></div></form>`,'PAYMENT ALREADY COMPLETED');
}
async function exportTaxes(){
 if(!financeAccess())throw Error('Financial access required.');
 const all=await api('export'),data=taxSummary(all.items,all.files,taxYear,all.company.settings);
 const yearRecords=all.items.filter(i=>String(i.payload.taxYear||i.payload.date||i.created_at).startsWith(taxYear));
 const rows=[['Tax year','Record type','Payment / record date','Description','Amount','Tax type','Jurisdiction','Tax period','Category','Review status','Payment reference','Attachment references'],...yearRecords.map(i=>[i.payload.taxYear||String(i.payload.date||i.created_at).slice(0,4),labels[i.kind]||i.kind,i.payload.date,i.payload.description,i.payload.amount,i.payload.taxType,i.payload.jurisdiction,i.payload.taxPeriod,i.payload.category,i.payload.taxReview||(['expense','fuel','fee'].includes(i.kind)?'needs_review':''),i.payload.paymentRef,all.files.filter(f=>f.item_id===i.id).map(f=>f.name+' ['+f.bucket+'/'+f.path+']').join('; ')])];
 download('LEOS_Tax_Records_'+taxYear+'.csv',csv(rows),'text/csv;charset=utf-8');toast('Tax-year records exported with attachment references. Review tax treatment with your accountant.');
}
function navigate(next){if(!pages[next])return;page=next;search='';filter='all';if(!inviteToken)history.replaceState(null,'','#'+page);$('.sidebar').classList.remove('open');$('#mobile-menu').setAttribute('aria-expanded','false');syncDrawer();render();window.scrollTo({top:0,behavior:'instant'});}
function modal(content,label='LEOS PHOTOBOOKS'){ $('#modal-label').textContent=label;$('#modal-content').innerHTML=content;if(!$('#modal').open)$('#modal').showModal();}
function close(){ $('#modal').close();$('#modal-content').innerHTML='';}
function formError(form,e){const target=form.querySelector('.form-error');if(target)target.textContent=e.message;else toast(e.message);}
async function submitTask(form,task){if(busy)return;busy=true;const buttons=[...form.querySelectorAll('button[type="submit"],button:not([type])')];buttons.forEach(b=>b.disabled=true);try{await task();}catch(e){formError(form,e);}finally{busy=false;buttons.forEach(b=>b.disabled=false);}}
function authForm(mode='login'){
 const signup=mode==='signup',reset=mode==='reset',recover=mode==='recover';
 modal(`<h2 id="modal-title">${recover?'Set a new password.':reset?'Find your way back.':signup?'A workspace for your business.':'Welcome back.'}</h2><p class="lead">${recover?'Choose a new password for your account.':reset?'We’ll send a password reset link to your email.':signup?'Create your account, verify your email, then set up your company.':'Sign in to your private company workspace.'}</p><form id="auth-form" data-mode="${mode}"><div class="form-grid">${!recover?'<label class="field full">Email address<input name="email" type="email" autocomplete="username" required placeholder="you@company.com"></label>':''}${!reset?'<label class="field full">Password<input name="password" type="password" autocomplete="'+(signup||recover?'new-password':'current-password')+'" minlength="8" required placeholder="At least 8 characters"></label>':''}</div><div class="form-error" role="alert"></div><button class="btn primary" style="width:100%;margin-top:22px" type="submit">${recover?'Update password':reset?'Send reset link':signup?'Create account':'Sign in'} ${icon('arrow')}</button></form>${!recover?`<div class="auth-options"><button data-action="auth-${signup?'login':'signup'}">${signup?'Already have an account?':'Create an account'}</button>${!reset?'<button data-action="auth-reset">Forgot password?</button>':''}</div>`:''}`,'YOUR PRIVATE ACCOUNT');
}
function createCompany(){if(!state.user){authForm('signup');return;}modal(`<h2 id="modal-title">A new home for your company.</h2><p class="lead">Each company has a separate team, records and subscription. You can own up to three company workspaces.</p><form id="create-company-form"><label class="field">Company / business name<input name="name" required minlength="2" maxlength="90" placeholder="Your business name" autocomplete="organization"></label><div style="margin-top:16px">${selectField('Business type','businessType',businessTypes,'general')}</div><div class="form-error" role="alert"></div><div class="form-actions"><button class="btn primary" type="submit">Create workspace ${icon('arrow')}</button></div></form>`,'NEW COMPANY');}
function field(label,name,value='',type='text',extra='',full=false){return `<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function selectField(label,name,options,value='',full=false){return `<label class="field ${full?'full':''}">${label}<select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
function recordForm(kind='expense',item){
 if(!state.company)return state.user?createCompany():authForm();
 if(!canWrite(kind))return toast('Your company role cannot add or edit this record type.');
 const p=item?.payload||{},load=kind==='load',truck=kind==='truck',ops=opKinds.includes(kind),financial=financeKinds.includes(kind);
 const statuses=kind==='taxDeadline'?[['open','Open'],['done','Done']]:['income','contribution','taxPayment'].includes(kind)?[['paid','Recorded / paid']]:['invoice','bill'].includes(kind)?[['open','Unpaid']]:load?[['scheduled','Scheduled'],['in_transit','In transit'],['completed','Completed']]:truck?[['active','Active'],['out_of_service','Out of service']]:[['open','Open'],['done','Done'],['paid','Paid']];
 let fields=field(truck?'Truck name / description':'Description','description',p.description,'text','required maxlength="500"',true)+field('Record date','date',p.date||today(),'date','required')+selectField('Status','status',statuses,p.status||statuses[0][0]);
 if(['invoice','bill'].includes(kind))fields+=field(kind==='invoice'?'Customer':'Vendor','customer',p.customer)+field('Reference number','reference',p.reference)+field('Due date','dueDate',p.dueDate,'date');
 if(['taxPayment','taxDeadline'].includes(kind))fields+=selectField('Tax type','taxType',taxTypes,p.taxType||'income_estimate')+field('Tax year this applies to','taxYear',p.taxYear||taxYear,'number','min="1900" max="2199" step="1" required')+field('Jurisdiction / agency','jurisdiction',p.jurisdiction)+field('Tax period (optional)','taxPeriod',p.taxPeriod)+field('Confirmation / payment reference','paymentRef',p.paymentRef);
 if(['expense','fuel','fee'].includes(kind))fields+=selectField('Tax review status','taxReview',[['needs_review','Needs accountant review'],['reviewed','Reviewed'],['not_deductible','Marked not deductible']],p.taxReview||'needs_review')+field('Bookkeeping category','category',p.category);
 if(kind==='income')fields+=field('Customer / source','customer',p.customer)+field('Income category','category',p.category);
 if(financial)fields+=field(load?'Gross load rate ($)':'Amount ($)','amount',p.amount??'','number','min="0" step="0.01" required');
 if(load)fields+=selectField('Pay calculation','payMode',[['percent','Percent of gross'],['cpm','Pay per mile'],['gross','Full gross rate']],p.payMode||'percent')+field('Pay per mile ($)','payPerMile',p.payPerMile||'','number','min="0" step="0.01"')+field('Load / reference number','loadNo',p.loadNo)+field('Origin','origin',p.origin)+field('Destination','destination',p.destination)+field('Pickup date','pickupDate',p.pickupDate,'date')+field('Delivery date','deliveryDate',p.deliveryDate,'date')+field('Paid / earned miles','miles',p.miles||'','number','min="0" step="0.1"')+field('Your load share (%)','loadShare',p.loadShare??state.company.settings.loadShare??100,'number','min="0" max="100" step="0.01"');
 if(['fuel','expense','fee'].includes(kind))fields+=selectField('Paid by','paidBy',[['company','This business / own money'],['carrier','Carrier card (business deduction)'],['other','Other company (not our expense)']],p.paidBy||'company')+field('Vendor / category','vendor',p.vendor||p.category);
 if(kind==='fuel')fields+=field('Confirmed fuel reimbursement ($)','credit',p.credit||'','number','min="0" step="0.01"')+field('Gallons','gallons',p.gallons||'','number','min="0" step="0.001"')+field('Price per gallon ($)','unitPrice',p.unitPrice||'','number','min="0" step="0.001"');
 if(truck)fields+=field('Unit number','unit',p.unit)+field('Make','make',p.make)+field('Model','model',p.model)+field('Year','year',p.year)+field('VIN','vin',p.vin)+field('Odometer (mi)','odometer',p.odometer||'','number','min="0" step="1"');
 if(ops)fields+=(kind==='taxDeadline'?'':field('Vehicle / unit','vehicle',p.vehicle))+field('Due / renewal date','dueDate',p.dueDate,'date');
 if(kind==='settlement')fields+=field('Payment reference','paymentRef',p.paymentRef)+selectField('Match to a company load','settlementId',[['','No linked load'],...state.items.filter(i=>i.kind==='load').map(i=>[i.id,(i.payload.loadNo||'Load')+' · '+i.payload.description])],p.settlementId||'');
 if(manager()||state.role==='dispatcher')fields+=selectField('Assign to','assignedTo',[['','Company record'],...state.members.map(m=>[m.user_id,m.email+' · '+titleCase(m.role)])],item?.assigned_to||'');
 fields+=`<label class="field full">Notes<textarea name="notes" maxlength="8000">${esc(p.notes||'')}</textarea></label><label class="field full">Attach receipt / document (optional)<input name="attachment" type="file" accept="application/pdf,image/jpeg,image/png,image/webp"><small>PDF or image · Up to 10 MB · Visible to authorized company members.</small></label>`;
 modal(`<h2 id="modal-title">${item?'Edit':'New'} ${esc(labels[kind].toLowerCase())}.</h2><p class="lead">${load?'Track the rate now. Update delivery and payment status as the load moves.':kind==='settlement'?'Settlements are tracked for matching, not counted again as load revenue.':kind==='draw'?'Owner draws are tracked separately from business expenses.':'Saved privately to '+esc(state.company.name)+'.'}</p><form id="record-form" data-kind="${kind}" data-id="${item?.id||''}" data-new-id="${crypto.randomUUID()}" data-version="${item?.version||''}" data-company="${state.company.id}"><div class="form-grid">${fields}</div><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="btn secondary" data-action="close">Cancel</button><button type="submit" class="btn primary">Save ${esc(labels[kind].toLowerCase())} ${icon('check')}</button></div></form>`,'COMPANY RECORD');
}
function chooseKind(opsOnly=false){if(!state.company)return createCompany();const kinds=(opsOnly?opKinds:financeKinds).filter(k=>!(generalMode()&&['load','fuel','fee','settlement'].includes(k))).filter(canWrite);if(!kinds.length)return toast('Your role cannot create records in this section.');modal(`<h2 id="modal-title">What are we adding?</h2><p class="lead">Choose the record type. It will be saved to ${esc(state.company.name)}.</p><div class="quick-list" style="grid-template-columns:1fr 1fr">${kinds.map(k=>`<button data-action="new-kind" data-kind="${k}">${icon(k==='load'?'truck':opKinds.includes(k)?'tool':'book')}${labels[k]}</button>`).join('')}</div>`,'NEW RECORD');}
function detail(id){const item=state.items.find(i=>i.id===id);if(!item)return;const p=item.payload;const locked=!!(p.invoiceId||p.billId||p.sourceInvoiceId||p.sourceBillId||p.paymentConfirmedAt||(['invoice','bill','load'].includes(item.kind)&&p.status==='paid'));const files=state.files.filter(f=>f.item_id===id);const entries=Object.entries(p).filter(([k,v])=>!['photos','rawText','documents','anchor','id','kind'].includes(k)&&v!==''&&v!==null&&typeof v!=='object');modal(`<h2 id="modal-title">${esc(p.description)}</h2><div class="badge-row">${statusTag(p.status)}<span class="tag">${esc(labels[item.kind])}</span></div><div class="detail-grid">${entries.map(([k,v])=>`<div><small>${esc(titleCase(k.replace(/([A-Z])/g,' $1')))}</small><p>${k==='amount'?money(v):esc(v)}</p></div>`).join('')}</div>${files.length?'<h3>Attachments</h3><div class="detail-files">'+files.map(f=>`<button class="btn secondary small" data-action="open-file" data-id="${f.id}">${icon('file')}${esc(f.name)}</button>`).join('')+'</div>':''}${locked?'<p class="section-note">Paid documents and their linked payment entries are locked to preserve the audit trail.</p>':''}<div class="form-actions">${financeAccess()&&(['invoice','bill'].includes(item.kind)||item.kind==='load'&&p.status==='completed')&&p.status!=='paid'?`<button class="btn primary" data-action="record-payment" data-id="${id}">Confirm payment</button>`:''}${manager()&&!locked?`<button class="btn danger" data-action="archive" data-id="${id}">Archive</button>`:''}${!locked&&canWrite(item.kind)&&(!['driver','staff'].includes(state.role)||item.created_by===state.user.id)?`<button class="btn primary" data-action="edit-record" data-id="${id}">Edit record</button>`:''}</div>`,'RECORD DETAILS');}
function uploadForm(){if(!state.company)return createCompany();modal(`<h2 id="modal-title">Keep the paperwork together.</h2><p class="lead">Upload a private document to ${esc(state.company.name)}.</p><form id="upload-form"><div class="form-grid"><label class="field full">PDF or image<input name="file" type="file" accept="application/pdf,image/jpeg,image/png,image/webp" required><small>Up to 10 MB. Files stay in private company storage.</small></label>${selectField('Attach to a record (optional)','itemId',[['','Company document'],...state.items.filter(i=>canWrite(i.kind)).map(i=>[i.id,(labels[i.kind]||i.kind)+' · '+i.payload.description])],'',true)}</div><div class="form-error" role="alert"></div><div class="form-actions"><button type="submit" class="btn primary">Upload document ${icon('file')}</button></div></form>`,'COMPANY DOCUMENT');}
function inviteForm(){if(!manager())return toast('Owner or administrator access required.');modal(`<h2 id="modal-title">Bring your team along.</h2><p class="lead">The invite is tied to this email address. You’ll get a link to share directly; no email is sent automatically.</p><form id="invite-form"><div class="form-grid">${field('Team member’s email','email','','email','required',true)}${selectField('Company role','role',[['staff','Staff · Own & assigned records'],...(!generalMode()?[['driver','Driver · Own & assigned records'],['dispatcher','Dispatcher · Loads & operations']]:[]),['bookkeeper','Bookkeeper · Financial records'],...(state.role==='owner'?[['admin','Administrator · Company management']]:[])],generalMode()?'staff':'driver',true)}</div><div class="form-error" role="alert"></div><div class="form-actions"><button class="btn primary" type="submit">Create invite link ${icon('team')}</button></div></form>`,'TEAM INVITATION');}
function importForm(){modal(`<h2 id="modal-title">Bring your records forward.</h2><p class="lead">Copy your personal bookkeeping records and link their original receipt photos to <strong>${esc(state.company.name)}</strong>. Your original records and files will stay unchanged.</p><div class="notice">Authorized company members will be able to see these copies and receipts. Later edits won’t sync between your personal records and company copies. Repeating this import won’t overwrite existing company copies.</div><form id="import-form"><label class="checkline"><input type="checkbox" required>I want to share copies of my personal records with this company.</label><div class="form-error" role="alert"></div><div class="form-actions"><button class="btn primary" type="submit">Copy my records ${icon('arrow')}</button></div></form>`,'PERSONAL → COMPANY');}
function memberForm(id){const member=state.members.find(m=>m.user_id===id);if(!member||state.role!=='owner')return;modal(`<h2 id="modal-title">Manage team access.</h2><p class="lead">${esc(member.email)} · ${esc(state.company.name)}</p><form id="member-form" data-id="${id}">${selectField('Role','role',[['admin','Administrator'],['staff','Staff'],['dispatcher','Dispatcher'],['driver','Driver'],['bookkeeper','Bookkeeper']],member.role)}<div class="form-error" role="alert"></div><div class="form-actions"><button class="btn danger" type="button" data-action="remove-member" data-id="${id}">Remove from company</button><button class="btn primary" type="submit">Save role</button></div></form>`,'TEAM ACCESS');}
function download(name,contents,type){const url=URL.createObjectURL(new Blob([contents],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function exportCsv(){if(['driver','staff'].includes(state.role))throw Error('Company exports require additional access.');const result=await api('export');const rows=[['Type','Date','Description','Load reference','Status','Amount','Miles','Origin','Destination','Notes'],...result.items.map(i=>[labels[i.kind]||i.kind,i.payload.date,i.payload.description,i.payload.loadNo,i.payload.status,i.payload.amount,i.payload.miles,i.payload.origin,i.payload.destination,i.payload.notes])];download('LEOS_Company_Records_'+today()+'.csv',csv(rows),'text/csv;charset=utf-8');toast('Company records exported. Attachments remain in Documents.');}
async function loadPlatform(){const seq=sequence;try{const data=await api('platform_overview');if(page!=='platform'||seq!==sequence)return;$('#main').innerHTML=heading('PLATFORM OWNER','Your companies, at a glance.','Account and subscription status across LEOS PhotoBooks.')+`<div class="stat-grid">${stat('Companies',data.companies.length,'Registered workspaces','fleet')}${stat('Active subscriptions',data.companies.filter(c=>c.subscription_status==='active').length,'Confirmed by the payment provider','card')}${stat('Early-access companies',data.companies.filter(c=>c.subscription_status==='preview').length,'No active subscription charge','team')}${stat('Needs attention',data.companies.filter(c=>['past_due','unpaid'].includes(c.subscription_status)).length,'Billing follow-up','clock')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Company</th><th>Plan</th><th>Subscription</th><th>Created</th></tr></thead><tbody>${data.companies.map(c=>`<tr><td><strong>${esc(c.name)}</strong>${c.suspended?'<small>Suspended</small>':''}</td><td>${esc(titleCase(c.plan))}</td><td>${statusTag(c.subscription_status)}</td><td>${dateLabel(c.created_at)}</td></tr>`).join('')||'<tr><td colspan="4" class="table-empty">No companies registered yet.</td></tr>'}</tbody></table></div></section><div class="section-note">${icon('info')}This overview shows company status only. It does not grant access to another company’s bookkeeping records or receipt files.</div>`;}catch(e){toast(e.message);}}
async function acceptInvitation(){if(!inviteToken)return;if(!state.user){authForm('login');return;}modal(`<h2 id="modal-title">Join your company workspace.</h2><p class="lead">You’re signed in as ${esc(state.user.email)}. This invitation must match your verified email address.</p><form id="accept-form"><div class="form-error" role="alert"></div><div class="form-actions"><button type="submit" class="btn primary">Accept invitation ${icon('team')}</button></div></form>`,'TEAM INVITATION');}

document.addEventListener('click',async event=>{
 const nav=event.target.closest('[data-page]');if(nav){navigate(nav.dataset.page);return;}
 const filteredButton=event.target.closest('[data-filter]');if(filteredButton){filter=filteredButton.dataset.filter;render();return;}
 const target=event.target.closest('[data-action]');if(!target)return;
 const action=target.dataset.action,id=target.dataset.id;
 try{
  if(action==='close')return close();
  if(action.startsWith('auth-'))return authForm(action.slice(5));
  if(action==='login')return authForm();
  if(action==='create-company')return createCompany();
  if(action==='add-record')return chooseKind();
  if(action==='add-task')return chooseKind(true);
  if(action==='new-kind')return recordForm(target.dataset.kind);
  if(action==='add-load')return recordForm('load');
  if(action==='add-expense')return recordForm('expense');
  if(action==='add-truck')return recordForm('truck');
  if(action==='add-maintenance')return recordForm('maintenance');
  if(action==='detail')return detail(id);
  if(action==='edit-record')return recordForm(state.items.find(i=>i.id===id).kind,state.items.find(i=>i.id===id));
  if(action==='scan-delivery'){navigate('loads');$('#delivery-photo')?.click();return;}
  if(action==='scan-file'){await scanSavedDelivery(id);return;}
  if(action==='upload')return uploadForm();
  if(action==='invite')return inviteForm();
  if(action==='import')return importForm();
  if(action==='edit-member')return memberForm(id);
  if(action==='structure-settings'){navigate('settings');return;}
  if(action==='tax-export')return exportTaxes();
  if(action==='record-payment')return paymentForm(id);
  if(action==='add-income')return recordForm('income');
  if(action==='add-invoice')return recordForm('invoice');
  if(action==='add-bill')return recordForm('bill');
  if(action==='add-tax-payment')return recordForm('taxPayment');
  if(action==='add-tax-deadline')return recordForm('taxDeadline');
  if(action==='print')return window.print();
  if(action==='reload')return bootstrap();
  if(action==='more'){target.disabled=true;await more();return;}
  if(action==='csv'){target.disabled=true;await exportCsv();target.disabled=false;return;}
  if(action==='export'){target.disabled=true;const result=await api('export');download('LEOS_Company_Backup_'+today()+'.json',JSON.stringify(result,null,2),'application/json');target.disabled=false;toast('Company backup downloaded. Original attachments remain in Documents.');return;}
  if(action==='open-file'){
   const windowRef=window.open('about:blank','_blank');target.disabled=true;
   try{const data=await api('file_url',{fileId:id});if(windowRef){windowRef.opener=null;windowRef.location.replace(data.url);}else toast('Allow pop-ups to open your private document.');}catch(e){windowRef?.close();throw e;}finally{target.disabled=false;}return;
  }
  if(action==='archive'){
   modal(`<h2 id="modal-title">Archive this record?</h2><p class="lead">It will leave active reports but remain in company exports. No attached receipt is deleted.</p><form id="archive-form" data-id="${id}"><div class="form-error"></div><div class="form-actions"><button type="button" class="btn secondary" data-action="close">Cancel</button><button type="submit" class="btn danger">Archive record</button></div></form>`,'COMPANY RECORD');return;
  }
  if(action==='remove-member'){
   modal(`<h2 id="modal-title">Remove company access?</h2><p class="lead">This member will lose access to the company. Their company records and documents remain stored.</p><form id="remove-member-form" data-id="${id}"><div class="form-error"></div><div class="form-actions"><button type="button" class="btn secondary" data-action="close">Cancel</button><button class="btn danger" type="submit">Remove member</button></div></form>`,'TEAM ACCESS');return;
  }
  if(action==='revoke-invite'){target.disabled=true;await api('revoke_invite',{id});await refresh();toast('Invitation revoked.');return;}
  if(action==='copy-invite'){await navigator.clipboard.writeText($('#invite-link').value);toast('Invitation link copied. Share it only with the intended teammate.');return;}
  if(action==='choose-plan'){
   modal(`<h2 id="modal-title">Choose your billing interval.</h2><p class="lead">${esc(titleCase(target.dataset.plan))} · Review the final price in Stripe Checkout before subscribing.</p><form id="checkout-form" data-plan="${target.dataset.plan}">${selectField('Billing interval','interval',[['monthly','Monthly'],['yearly','Yearly']],'monthly')}<div class="form-error"></div><div class="form-actions"><button type="submit" class="btn primary">Continue to checkout ${icon('arrow')}</button></div></form>`,'SUBSCRIPTION');return;
  }
  if(action==='portal'){target.disabled=true;const result=await api('billing_portal');location.assign(result.url);return;}
  if(action==='logout'){await client.auth.signOut();wipe();render();return;}
 }catch(e){target.disabled=false;toast(e.message);}
});
document.addEventListener('change',event=>{if(event.target.id==='company-switch')loadCompany(event.target.value);if(event.target.id==='tax-year'){taxYear=event.target.value;render();}if(event.target.id==='period'){month=event.target.value;render();}});
document.addEventListener('input',event=>{if(event.target.id==='search-records'){search=event.target.value;const focus=event.target.selectionStart;render();$('#search-records')?.focus();$('#search-records')?.setSelectionRange(focus,focus);}});
document.addEventListener('submit',event=>{
 const form=event.target;if(!form.id)return;event.preventDefault();
 submitTask(form,async()=>{
  const data=Object.fromEntries(new FormData(form));
  if(form.id==='auth-form'){
   const mode=form.dataset.mode;let result;
   if(mode==='reset'){result=await client.auth.resetPasswordForEmail(data.email,{redirectTo:location.origin+'/company.html#recovery'});if(result.error)throw result.error;toast('If this account exists, a reset email has been requested.');close();return;}
   if(mode==='recover'){result=await client.auth.updateUser({password:data.password});if(result.error)throw result.error;toast('Password updated.');close();return;}
   if(mode==='signup')result=await client.auth.signUp({email:data.email,password:data.password,options:{emailRedirectTo:location.origin+'/company.html'}});
   else result=await client.auth.signInWithPassword({email:data.email,password:data.password});
   if(result.error)throw result.error;
   if(mode==='signup'&&!result.data.session){form.reset();toast('Check your email to verify your account, then sign in.');return;}
   close();return;
  }
  if(form.id==='create-company-form'){const result=await api('create_company',{name:data.name,businessType:data.businessType});close();await bootstrap(result.company.id);toast('Your company workspace is ready.');return;}
  if(form.id==='record-form'){
   const attachment=data.attachment;delete data.attachment;const assignedTo=data.assignedTo;delete data.assignedTo;
   if(attachment?.size>10485760)throw Error('Attachment must be under 10 MB.');
   const companyId=form.dataset.company;
   const saved=await api('save_item',{kind:form.dataset.kind,payload:data,assignedTo,newId:form.dataset.newId,id:form.dataset.id||undefined,version:Number(form.dataset.version)||undefined},companyId);
   let attachmentError;
   if(attachment?.size){const f=new FormData();f.set('file',attachment);f.set('itemId',saved.id);try{await api('upload_file',f,companyId);}catch(e){attachmentError=e.message;}}
   close();await refresh();toast(attachmentError?'Record saved. Attachment failed: '+attachmentError+' Upload it from Documents.':'Record saved to your company.');return;
  }
  if(form.id==='upload-form'){await api('upload_file',new FormData(form));close();await refresh();toast('Document uploaded privately.');return;}
  if(form.id==='payment-form'){const cid=form.dataset.company,uid=form.dataset.user;if(state.user?.id!==uid)throw Error('Account changed. Reopen Payments.');if(!data.verified)throw Error('Confirm you verified the full payment.');const result=await api('record_installment',{paymentId:form.dataset.paymentId,amount:Number(data.amount),paymentType:data.paymentType,id:form.dataset.id,version:Number(form.dataset.version),date:data.date,method:data.method,reference:data.reference||''},cid);if(state.company?.id!==cid||state.user?.id!==uid)return;close();await refresh();toast(result.alreadyRecorded?'This payment was already recorded; no duplicate was added.':'Payment confirmed. Balances, reports and reserve target updated.');return;}
  if(form.id==='company-settings'){await api('update_company',data);await refresh();toast('Company preferences saved.');return;}
  if(form.id==='invite-form'){
   const result=await api('create_invite',data);await refresh();modal(`<h2 id="modal-title">Their place is ready.</h2><p class="lead">Share this link with ${esc(data.email)}. They must sign in with that verified email. The link expires in seven days.</p><div class="invite-result"><strong>Private invitation link</strong><input id="invite-link" aria-label="Private invitation link" readonly value="${esc(result.url)}"><button class="btn secondary small" data-action="copy-invite">Copy link</button></div><p class="section-note">No invitation email was sent automatically.</p>`,'TEAM INVITATION');return;
  }
  if(form.id==='accept-form'){const result=await api('accept_invite',{token:inviteToken});inviteToken=null;history.replaceState(null,'','#dashboard');page='dashboard';close();await bootstrap(result.companyId);toast('You’ve joined the company.');return;}
  if(form.id==='member-form'){await api('change_role',{userId:form.dataset.id,role:data.role});close();await refresh();toast('Team role updated.');return;}
  if(form.id==='remove-member-form'){await api('remove_member',{userId:form.dataset.id});close();await refresh();toast('Company access removed.');return;}
  if(form.id==='archive-form'){await api('archive_item',{id:form.dataset.id});close();await refresh();toast('Record archived. Original documents remain stored.');return;}
  if(form.id==='import-form'){const result=await api('import_legacy');close();await refresh();toast(result.copied+' records copied. Personal originals remain unchanged.');return;}
  if(form.id==='checkout-form'){const result=await api('checkout',{plan:form.dataset.plan,interval:data.interval});location.assign(result.url);return;}
 });
});
function syncDrawer(){const mobile=matchMedia('(max-width:1000px)').matches;$('.sidebar').inert=mobile&&!$('.sidebar').classList.contains('open');}
function closeDrawer(){$('.sidebar').classList.remove('open');$('#mobile-menu').setAttribute('aria-expanded','false');syncDrawer();}
$('#mobile-menu').onclick=()=>{const open=$('.sidebar').classList.toggle('open');$('#mobile-menu').setAttribute('aria-expanded',String(open));syncDrawer();};
$('#close-menu').onclick=()=>{closeDrawer();$('#mobile-menu').focus();};
window.addEventListener('resize',syncDrawer);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.sidebar').classList.contains('open')){closeDrawer();$('#mobile-menu').focus();}});syncDrawer();
$('#close-modal').onclick=close;
$('#new-company').onclick=createCompany;
$('#account').onclick=()=>{
 if(!state.user)return authForm();
 modal(`<h2 id="modal-title">Your account.</h2><p class="lead">${esc(state.user.email)}</p><div class="actions">${button('Switch company','close','secondary','fleet')}<button class="btn secondary" data-action="logout">Sign out</button></div>`,'PRIVATE ACCOUNT');
};
document.addEventListener('click',e=>{if($('.sidebar').classList.contains('open')&&!e.target.closest('.sidebar')&&!e.target.closest('#mobile-menu')){$('.sidebar').classList.remove('open');$('#mobile-menu').setAttribute('aria-expanded','false');syncDrawer();}});
window.addEventListener('online',()=>{toast('Connection restored.');if(state.company)refresh().catch(e=>toast(e.message));});
window.addEventListener('offline',()=>toast('You’re offline. Reconnect before changing company records.'));
window.addEventListener('hashchange',()=>{const hash=location.hash.slice(1);if(pages[hash])navigate(hash);});
let lastAuthUser;
async function onSession(session,event){
 const user=session?.user;if(event==='PASSWORD_RECOVERY'){state.user=user;authForm('recover');return;}
 if(user?.id===lastAuthUser&&event!=='INITIAL_SESSION')return;
 lastAuthUser=user?.id;const authSeq=++authSequence;
 if(!user){wipe();render();return;}
 wipe();state.user=user;chrome();
 if(!user.email_confirmed_at){render();toast('Verify your email to open a company workspace.');return;}
 try{await bootstrap();if(authSeq!==authSequence)return;if(inviteToken)await acceptInvitation();}
 catch(e){if(authSeq!==authSequence)return;$('#main').innerHTML=`<section class="card">${empty('info','Let’s reconnect your workspace.',esc(e.message),button('Try again','reload'))}</section>`;}
}
async function init(){
 if(!client){$('#main').innerHTML='<div class="notice">The account library could not load. Check your connection and refresh the page.</div>';return;}
 const hash=location.hash.slice(1);if(pages[hash])page=hash;
 client.auth.onAuthStateChange((event,session)=>setTimeout(()=>onSession(session,event),0));
 const {data,error}=await client.auth.getSession();if(error){toast(error.message);render();return;}
 if(lastAuthUser===undefined)await onSession(data.session,'INITIAL_SESSION');
 if(new URLSearchParams(location.search).get('billing')==='success')toast('Checkout completed. Subscription confirmation may take a moment; refresh to check its status.');
}
init().catch(e=>toast(e.message));

function initTripPlanner(){
 const companyId=state.company.id,userId=state.user.id;
 const root=document.querySelector('#trip-planner');
 const isCurrent=()=>state.company?.id===companyId&&state.user?.id===userId&&page==='trips';
 mountTrip({root,isCurrent,canSave:canWrite('load'),invoke:async body=>{
  const {data,error}=await client.functions.invoke('leos-trip-plan',{body});
  if(error){let detail;try{detail=await error.context?.json();}catch{}throw Error(detail?.error||error.message);}return data;
 },save:async(payload,file,newId)=>{
  if(!isCurrent())throw Error('Company changed. Reopen the trip planner.');
  const result=await api('save_item',{kind:'load',payload,newId},companyId);
  if(file?.size){const form=new FormData();form.set('file',file);form.set('itemId',result.id);try{await api('upload_file',form,companyId);}catch(e){result.attachmentError=e.message;}}
  return result;
 }});
}

function initScheduling(){
 const company=state.company,userId=state.user.id,root=document.querySelector('#scheduling-root');
 mountScheduling({root,company,onInvoice:async id=>{const result=await api('invoice_appointment',{id},company.id);if(state.company?.id!==company.id||state.user?.id!==userId)return;await refresh();navigate('payments');paymentForm(result.id);},isCurrent:()=>state.company?.id===company.id&&state.user?.id===userId&&page==='appointments',request:async body=>{
 const {data,error}=await client.functions.invoke('leos-booking',{body:{...body,companyId:company.id}});
 if(error){let detail;try{detail=await error.context?.json();}catch{}throw Error(detail?.error||error.message);}return data;
 }});
}

function initSmartUpload(){
 const root=$('#main'),input=root.querySelector('#smart-document'),cid=state.company.id,uid=state.user.id;
 const active=()=>state.company?.id===cid&&state.user?.id===uid&&root.querySelector('#smart-document')===input;
 mountSmartUpload({root,active,getState:()=>state,read:readDocumentPhoto,canWrite,request:(action,body)=>{if(!active())throw Error('Account or company changed');return api(action,body,cid);},refresh:async()=>{if(active())await refresh();},review:detail,delivery:photoProcessor?file=>photoProcessor(file):null});
}

function initPhotoCompletion(){
 const companyId=state.company.id,userId=state.user.id,root=$('#main'),input=root.querySelector('#delivery-photo');
 const active=()=>state.company?.id===companyId&&state.user?.id===userId&&['loads','documents','dashboard'].includes(page)&&root.querySelector('#delivery-photo')===input;
 photoProcessor=mountPhotoCompletion({root,active,getState:()=>state,request:async(action,body)=>{if(!active())throw Error('Company or account changed. Reopen Loads.');return api(action,body,companyId);},refresh:async()=>{if(active())await refresh();},edit:item=>recordForm('load',item),notify:message=>{if(state.company?.id===companyId&&state.user?.id===userId)toast(message);}});
}

async function scanSavedDelivery(id){
 const companyId=state.company?.id,userId=state.user?.id,file=state.files.find(f=>f.id===id),process=photoProcessor;
 if(!file||!process||!canWrite('load'))throw Error('Open Documents in the correct company first.');
 const current=()=>state.company?.id===companyId&&state.user?.id===userId&&photoProcessor===process;
 const signed=await api('file_url',{fileId:id},companyId);if(!current())return;
 const response=await fetch(signed.url);if(!response.ok)throw Error('The private image could not be downloaded. Try again.');
 const blob=await response.blob();if(!current())return;
 await process(new File([blob],file.name,{type:file.mime||blob.type}));
}
